def count_triangles(n, m, edges):
    # Create a graph from Alice's edges
    graph = {i: set() for i in range(1, n + 1)}
    for a, b in edges:
        graph[a].add(b)
        graph[b].add(a)

    # Count triangles in Alice's graph
    alice_triangles = 0
    for a in range(1, n + 1):
        for b in graph[a]:
            for c in graph[b]:
                if c != a and c in graph[a]:
                    alice_triangles += 1

    # Bob's graph is the complement of Alice's graph
    bob_edges = []
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):
            if b not in graph[a]:
                bob_edges.append((a, b))

    # Create a graph from Bob's edges
    bob_graph = {i: set() for i in range(1, n + 1)}
    for a, b in bob_edges:
        bob_graph[a].add(b)
